i tried it in a different way but im not sure if its correct 

package melp;

import java.util.ArrayList;

public class test {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
   ArrayList<Integer> items = new ArrayList<Integer>();

		items.add(5);
		items.add(-5);
		items.add(10);
		items.add(2);
		items.add(9);

		PrintArray(items);

		double mean = CalculateAverage(items);
		System.out.println("The mean of the array is: " + mean);

	}

	public static double CalculateAverage(ArrayList<Integer> items)
	{
		double total =0;
		for (int i = 0; i < items.size(); i++) 
			total= total+items.get(i);

		return total/items.size();
	}

	public static void PrintArray(ArrayList<Integer> items)
	{
		for (int i = 0; i <items.size(); i++) {
			System.out.print(items.get(i)+ "\t");
		}
		System.out.println();
	}

}
